-- 1. New categories (only if missing)
ON CONFLICT (id) DO NOTHING;
SELECT setval('public.categories_id_seq', (SELECT MAX(id) FROM public.categories));

-- 2. Remove ALL current places and their dependent rows
DELETE FROM public.visits WHERE place_id IN (SELECT id FROM public.places);
DELETE FROM public.coupons WHERE place_id IN (SELECT id FROM public.places);
DELETE FROM public.place_routes WHERE place_id IN (SELECT id FROM public.places);
DELETE FROM public.user_favorites WHERE place_id IN (SELECT id FROM public.places);
UPDATE public.partner_applications SET place_id = NULL WHERE place_id IN (SELECT id FROM public.places);
DELETE FROM public.places;

